(()=>{'use strict';
const CATS=[['Groceries',403.76,'🛒'],['Gasoline',261.42,'⛽'],['Alcohol',233.64,'🍺'],['Subscriptions',189.91,'🔁'],['Medical',146.39,'🩺'],['Other Living Expenses',145.47,'🧾'],['Phone',132.78,'📱'],['Gambling',120,'🎲'],['Insurance',90.50,'🛡️'],['Fitness',63.95,'💪'],['Tobacco',19.32,'🚬']];
const DEBTS=[['OneMain',3635.49,34.45],['Chase Freedom',1173.80,26.74],['Upstart',2339.77,24.12]];
const KEY='spendwise-phone-v1',fmt=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
let data=load(),tab='home',month=today().slice(0,7),selectedCategory=null,expandedSub=null,incomeExpanded=false,calendarExpanded=false;
function load(){try{let a=JSON.parse(localStorage.getItem(KEY));if(a&&Array.isArray(a.transactions))return a}catch(e){}return{transactions:[],savings:1688.99,debts:Object.fromEntries(DEBTS.map(x=>[x[0],x[1]])),goal:11842,monthlyIncome:3591.01,monthlySavings:718.21,monthlyBudget:Object.fromEntries(CATS.map(x=>[x[0],x[1]])),financeLog:[]}}
function save(){localStorage.setItem(KEY,JSON.stringify(data))}
function migrate(){let changed=false;if(!Array.isArray(data.categories)){data.categories=CATS.map(([name,,icon])=>({name,icon}));changed=true}if(!data.monthOverrides){data.monthOverrides={};changed=true}if(!data.futureBudgets){data.futureBudgets=[];changed=true}if(!data.retirement){data.retirement={employee:35349,city:66784,asOf:'2026-11-13',a401:9090.99,a401Date:'2026-09-30',health:13698.27,healthDate:'2026-09-30',employeeRate:11.26,cityRate:21.13};changed=true}if(!Array.isArray(data.paychecks)){data.paychecks=[];changed=true}if(!Array.isArray(data.bills)){data.bills=[];changed=true}if(!data.rollovers){data.rollovers={};changed=true}if(!data.subcategories){data.subcategories={};changed=true}if(!Array.isArray(data.payrollYears)){data.payrollYears=PAYROLL_SEED.map(x=>({...x}));changed=true}if(Array.isArray(data.payrollYears)){const known={2021:1050,2022:1800,2023:750,2024:1800,2025:1800,2026:1500};for(const row of data.payrollYears){if(row.retirementHealthEmployer===undefined&&Object.prototype.hasOwnProperty.call(known,row.year)){row.retirementHealthEmployer=known[row.year];changed=true}}}if(changed)save()}
// Historical payroll summaries are data, not hard-coded financial calculations.
// 2026 is a YTD snapshot and must be replaced (not added) when a newer paystub arrives.
const PAYROLL_SEED=[
{year:2021,date:'2021-12-30',gross:28002.72,net:19384.22,taxes:4803.69,employee:2913.77,city:7094.68,a401:541.17,taxable:24255.11,retirementHealthEmployer:1050.00,source:'Final paystub',partial:true},
{year:2022,date:'2022-12-30',gross:50716.15,net:37059.44,taxes:6676.71,employee:5234.96,city:12445.25,a401:1046.11,taxable:43865.75,retirementHealthEmployer:1800.00,source:'Final paystub'},
{year:2023,date:'2023-12-29',gross:56106.86,net:39408.03,taxes:8840.42,employee:5893.05,city:13368.45,a401:1154.71,taxable:48393.57,retirementHealthEmployer:750.00,source:'Final paystub'},
{year:2024,date:'2024-12-27',gross:59844.80,net:41230.06,taxes:10066.59,employee:6560.23,city:14099.67,a401:1273.00,taxable:51444.97,retirementHealthEmployer:1800.00,source:'Final paystub'},
{year:2025,date:'2025-12-26',gross:60546.11,net:41581.09,taxes:10005.85,employee:6807.09,city:13947.10,a401:1336.06,taxable:51737.42,retirementHealthEmployer:1800.00,source:'Final paystub'},
{year:2026,date:'2026-11-13',gross:54898.52,net:37805.14,taxes:8956.47,employee:6051.52,city:11807.37,a401:1244.92,taxable:46890.33,retirementHealthEmployer:1500.00,source:'YTD paystub',partial:true}
];
migrate();
function payrollRows(){return [...data.payrollYears].sort((a,b)=>a.year-b.year)}
function payrollSum(field){return Math.round(payrollRows().reduce((sum,row)=>sum+Number(row[field]||0),0)*100)/100}
function totalCompensation(){return money(payrollSum('gross')+payrollSum('city')+payrollSum('a401')+payrollSum('retirementHealthEmployer'))}
function payrollDashboard(){let rows=payrollRows();return `<div class="sectionhead"><h2>Career compensation</h2><span class="pill">${rows.length} years</span></div><div class="card retirement-card"><div class="eyebrow">Lifetime total compensation · documented</div><h2 class="retirement-total">${fmt(totalCompensation())}</h2><div class="row earnings-row"><span>Take-home pay</span><b>${fmt(payrollSum('net'))}</b></div><div class="row earnings-row"><span>Taxes withheld</span><b class="taxes-red">${fmt(payrollSum('taxes'))}</b></div><p class="note">Total = gross wages + employer COPERS + employer 401(a) + documented employer retirement-health contributions. Employee retirement contributions are already in gross wages. Active medical, dental and insurance premiums are excluded. Retirement-health contribution history may be incomplete; this is not an account balance or cash available to spend.</p></div><div class="sectionhead"><h2>Annual earnings</h2><button class="pill" id="payrollUpdate" style="border:0;color:#e7f3ff">Update YTD</button></div>${rows.map((r,i)=>{let prev=rows[i-1],change=prev&&prev.gross?((r.gross/prev.gross-1)*100).toFixed(1):null;let comp=money(Number(r.gross||0)+Number(r.city||0)+Number(r.a401||0)+Number(r.retirementHealthEmployer||0));return `<details class="card" style="margin-bottom:10px"><summary style="cursor:pointer;display:flex;justify-content:space-between;gap:12px;align-items:center"><span><b>${r.year}${r.partial?' · Partial/YTD':''}</b><small style="display:block" class="muted">${esc(r.source)} · ${esc(r.date)}</small></span><span style="text-align:right"><b>${fmt(comp)}</b><small class="muted" style="display:block">Total compensation</small></span></summary><div class="row"><span>Gross wages</span><b>${fmt(r.gross)}</b></div><div class="row"><span>Take-home pay</span><b>${fmt(r.net)}</b></div><div class="row"><span>Taxes withheld</span><b class="taxes-red">${fmt(r.taxes)}</b></div><div class="row"><span>Federal taxable gross</span><b>${fmt(r.taxable)}</b></div><div class="row"><span>Employee COPERS (already in gross)</span><b>${fmt(r.employee)}</b></div><div class="row"><span>City COPERS</span><b>${fmt(r.city)}</b></div><div class="row"><span>Employer 401(a) contributions</span><b>${fmt(r.a401)}</b></div><div class="row"><span>Employer retirement healthcare contributions</span><b>${fmt(r.retirementHealthEmployer||0)}</b></div></details>`}).join('')}<p class="note">Employer retirement contributions are funding amounts, not guaranteed personal retirement balances. Payroll taxes withheld may differ from final taxes owed. W-2 taxable wages differ from gross earnings.</p>`}

function payrollEditor(){let y=Math.max(...data.payrollYears.map(r=>r.year)),r=data.payrollYears.find(x=>x.year===y);modal(`<h2>Update payroll year-to-date</h2><p class="note">Enter the YTD totals from your newest paystub. This replaces that year's previous snapshot and does not change your savings balance or record a new paycheck. Importing PDFs automatically is not enabled yet.</p><label class="field">Payroll year</label><input id="pyYear" type="number" min="2021" max="2100" value="${y}"><label class="field">Paystub date</label><input id="pyDate" type="date" value="${r.date}">${[['gross','YTD gross earnings'],['net','YTD net pay'],['taxes','YTD total taxes'],['taxable','YTD federal taxable gross'],['employee','YTD employee COPERS'],['city','YTD City COPERS'],['a401','YTD employer 401(a)'],['retirementHealthEmployer','YTD employer retirement healthcare contributions']].map(([k,label])=>`<label class="field">${label}</label><input id="py_${k}" type="number" min="0" step=".01" value="${r[k]??0}">`).join('')}<p id="pyError" class="note danger"></p><div class="btnrow"><button class="secondary" id="pyCancel">Cancel</button><button class="primary" id="pySave">Save snapshot</button></div>`);document.getElementById('pyCancel').onclick=close;document.getElementById('pyYear').onchange=()=>{let year=Number(document.getElementById('pyYear').value),row=data.payrollYears.find(x=>x.year===year);if(row){document.getElementById('pyDate').value=row.date;for(let k of ['gross','net','taxes','taxable','employee','city','a401','retirementHealthEmployer'])document.getElementById('py_'+k).value=row[k]}else{document.getElementById('pyDate').value=today();for(let k of ['gross','net','taxes','taxable','employee','city','a401','retirementHealthEmployer'])document.getElementById('py_'+k).value=''}};document.getElementById('pySave').onclick=()=>{let year=Number(document.getElementById('pyYear').value),date=document.getElementById('pyDate').value,fields={};for(let k of ['gross','net','taxes','taxable','employee','city','a401','retirementHealthEmployer']){let el=document.getElementById('py_'+k),n=Number(el.value);if(el.value.trim()===''||!Number.isFinite(n)||n<0){document.getElementById('pyError').textContent='Enter valid nonnegative YTD totals for every field.';return}fields[k]=Math.round(n*100)/100}if(!Number.isInteger(year)||year<2021||year>2100||!date||Number(date.slice(0,4))!==year||fields.net>fields.gross||fields.taxes>fields.gross){document.getElementById('pyError').textContent='Check the year, date, gross, net, and tax totals.';return}let old=data.payrollYears.find(x=>x.year===year);if(old&&date<old.date){document.getElementById('pyError').textContent='This is older than the stored snapshot. No changes were made.';return}data.payrollYears=data.payrollYears.filter(x=>x.year!==year);data.payrollYears.push({year,date,...fields,source:'Manually entered YTD paystub',partial:true});save();close();render()}}
const categories=()=>data.categories;
function getBudget(c,m=month){if(data.monthOverrides[m]&&Object.prototype.hasOwnProperty.call(data.monthOverrides[m],c))return Number(data.monthOverrides[m][c]);let future=data.futureBudgets.filter(x=>x.category===c&&x.start<=m).sort((a,b)=>b.start.localeCompare(a.start))[0];return Number(future?future.amount:(data.monthlyBudget[c]??0))}
const monthly=()=>data.transactions.filter(t=>t.date.slice(0,7)===month),spent=c=>monthly().filter(t=>t.category===c).reduce((s,t)=>s+t.amount,0),total=()=>monthly().reduce((s,t)=>s+t.amount,0),budget=()=>categories().reduce((s,c)=>s+getBudget(c.name),0);
function bar(spending,budgetAmount){let lo=Math.min(0,spending),hi=Math.max(0,budgetAmount,spending);if(hi===lo)return `<div class="mini"></div>`;let pct=v=>((v-lo)/(hi-lo)*100),zero=pct(0),limit=pct(Math.max(0,budgetAmount)),actual=pct(spending);let neg=spending<0;return `<div class="mini budget-track">${neg?`<div class="budget-negative" style="left:0;width:${zero}%"></div><span class="budget-marker" style="left:${zero}%">0</span>`:`<div class="budget-blue" style="left:0;width:${Math.min(actual,limit)}%"></div>`}${spending>budgetAmount&&budgetAmount>=0?`<div class="budget-excess" style="left:${limit}%;width:${actual-limit}%"></div><span class="budget-marker" style="left:${limit}%">${fmt(budgetAmount)}</span>`:''}</div>`}
function remainingColor(spending,b){if(b<=0)return spending>0?'rgb(245,105,111)':'rgb(168,240,182)';let ratio=(b-spending)/b;let neutral=[231,238,248],green=[90,214,143],red=[225,71,85],t=Math.min(1,Math.abs(ratio));let target=ratio>=0?green:red;return `rgb(${neutral.map((v,i)=>Math.round(v+(target[i]-v)*t)).join(',')})`}
function monthHeader(){let d=new Date(month+'-02T12:00:00');return `<div class="monthnav"><button data-month="-1" aria-label="Previous month">‹</button><button class="month-title" id="monthCalendar" aria-expanded="${calendarExpanded}">${d.toLocaleString('en-US',{month:'long',year:'numeric'})} ${calendarExpanded?'▴':'▾'}</button><button data-month="1" aria-label="Next month">›</button></div>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.getElementById('view').innerHTML=tab==='home'?home():tab==='history'?history():finances();bind()}
function home(){let t=total(),b=budget(),remaining=b-t,p=t/b*100;let days=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate(),now=today().slice(0,7)===month?new Date().getDate():month<today().slice(0,7)?days:0,daysLeft=Math.max(0,days-now);return `${monthHeader()}${calendarExpanded?inlineCalendar():''}<section class="hero"><div class="eyebrow">${remaining>=0?'Available to spend':'Over budget'}</div><h1>${fmt(Math.abs(remaining))}</h1><div class="muted">of ${fmt(b)} monthly living expenses</div><div class="track"><div class="fill ${p>100?'over':p>80?'warn':''}" style="width:${Math.min(100,p)}%"></div></div><div class="split"><div><span class="muted">Spent</span><strong>${fmt(t)}</strong></div><div><span class="muted">${month===today().slice(0,7)?'Per day left':'Transactions'}</span><strong>${month===today().slice(0,7)?fmt(Math.max(0,remaining)/Math.max(1,daysLeft)):monthly().length}</strong></div></div></section><button class="action" id="addBtn">＋ Add expense</button><div class="sectionhead"><h2>Category budgets</h2><span class="pill">${categories().length} categories</span></div>${categories().map(({name:c,icon})=>categoryAccordion(c,icon)).join('')}<p class="note">The category budgets reproduce your projected monthly amounts (${fmt(budget())} total). Debt payments and savings are tracked separately, not counted as living expenses.</p>`}

function txRows(a){return a.length?a.sort((x,y)=>y.date.localeCompare(x.date)).map(t=>`<div class="row tx"><div><b>${esc(t.note||t.subcategory||t.category)}</b><small>${esc(t.date)}</small></div><div class="right"><b>${fmt(t.amount)}</b><small><button data-edit="${esc(t.id)}">Edit</button></small></div></div>`).join(''):'<p class="muted">No expenses this month.</p>'}
function categoryAccordion(c,icon){let a=monthly().filter(t=>t.category===c),b=getBudget(c),sum=spent(c),subs=data.subcategories[c]||[],open=selectedCategory===c;return `<div class="card category-wrap"><button class="cat-toggle" data-category="${esc(c)}" aria-expanded="${open}"><div class="symbol">${esc(icon)}</div><div class="catmain"><b>${esc(c)}</b><div class="muted">${fmt(sum)} of ${fmt(b)}</div></div><div class="amount" style="color:${remainingColor(sum,b)}">${fmt(b-sum)} <span class="chevron">${open?'▾':'▸'}</span></div></button>${bar(sum,b)}${rolloverBadge(c)}${open?`<div class="category-inside">${c==='Subscriptions'?'':`<button class="secondary add-inline" data-add-cat="${esc(c)}">＋ Add expense</button>`}${subs.map(x=>{let sa=a.filter(t=>t.subcategory===x.name),opened=expandedSub===x.name;return `<div class="sub-wrap"><button class="sub-toggle" data-sub="${esc(x.name)}" aria-expanded="${opened}"><span>${subIcon(x.name)}</span><span class="sub-name">${esc(x.name)}</span><b>${fmt(sa.reduce((v,t)=>v+t.amount,0))}</b><span>${opened?'▾':'▸'}</span></button>${opened?`<div class="sub-inside"><button class="secondary add-inline" data-add-sub="${esc(x.name)}">＋ Add expense</button>${txRows(sa)}</div>`:''}</div>`}).join('')}${c==='Subscriptions'?'<button class="secondary add-inline" id="addSubscription">＋ Add subscription</button>':''}${subs.length?'<div class="subtle">Other transactions</div>':''}${txRows(a.filter(t=>!t.subcategory||!subs.some(x=>x.name===t.subcategory)))}</div>`:''}</div>`}
function subIcon(name){let icons={'Xbox Game Pass':'🎮','Netflix':'🎬','Amazon Prime':'📦','Peacock':'🦚','Spotify':'🎵','YouTube Premium':'▶️','Apple Music':'🎵','Disney+':'✨','Hulu':'📺'};let custom=data.subLogos?.[name];return custom?`<img class="sub-logo" src="${esc(custom)}" alt="">`:`<span class="sub-logo-fallback">${icons[name]||'🔁'}</span>`}
function emergencyGoal(){let first='2026-11',now=today().slice(0,7),actual=0,projected=0;for(let i=0;i<6;i++){let d=new Date(Number(first.slice(0,4)),Number(first.slice(5))-1+i,2),m=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;if(m<now){actual+=data.transactions.filter(t=>t.date.slice(0,7)===m).reduce((v,t)=>v+Number(t.amount),0)}else{projected+=categories().reduce((v,c)=>v+getBudget(c.name,m),0)}}if(now>'2027-04'){actual=0;projected=0;let d=new Date(Number(now.slice(0,4)),Number(now.slice(5))-1,2);for(let i=1;i<=6;i++){let k=new Date(d.getFullYear(),d.getMonth()-i,2),m=`${k.getFullYear()}-${String(k.getMonth()+1).padStart(2,'0')}`;actual+=data.transactions.filter(t=>t.date.slice(0,7)===m).reduce((v,t)=>v+Number(t.amount),0)}}return money(actual+projected+1000)}

function rolloverAmount(c){let mode=data.rollovers[c]||'none';if(mode==='none')return null;let start=mode==='year'?month.slice(0,4)+'-01':(data.rolloverStarts?.[c]||month);let d=new Date(start+'-02T12:00:00'),end=new Date(month+'-02T12:00:00'),sum=0;while(d<=end){let m=d.toISOString().slice(0,7);sum+=getBudget(c,m)-data.transactions.filter(t=>t.category===c&&t.date.slice(0,7)===m).reduce((a,t)=>a+t.amount,0);d.setMonth(d.getMonth()+1)}return Math.round(sum*100)/100}
function rolloverBadge(c){let v=rolloverAmount(c);return v===null?'':`<div class="subtle ${v<0?'danger':''}" style="margin-top:8px">Accumulated unspent budget: ${fmt(v)} · ${esc(data.rollovers[c])} · not cash</div>`}
function categoryDetail(){let c=selectedCategory,a=monthly().filter(t=>t.category===c).sort((x,y)=>y.date.localeCompare(x.date)),b=getBudget(c);return `${monthHeader()}<button class="secondary" id="backCategory">← All categories</button><h2 style="margin:18px 0">${esc(c)}</h2><div class="card"><div class="row"><span>Monthly budget</span><b>${fmt(b)}</b></div><div class="row"><span>Spent</span><b>${fmt(spent(c))}</b></div><div class="row"><span>Remaining</span><b>${fmt(b-spent(c))}</b></div>${rolloverBadge(c)}</div><button class="action" id="addCategoryExpense">＋ Add ${esc(c)} expense</button><div class="sectionhead"><h2>Transactions</h2><span class="pill">${a.length}</span></div><div class="card">${a.length?a.map(t=>`<div class="row tx"><div><b>${esc(t.note||t.subcategory||c)}</b><small>${esc(t.date)}${t.subcategory?' · '+esc(t.subcategory):''}</small></div><div class="right"><b>${fmt(t.amount)}</b><small><button data-edit="${esc(t.id)}">Edit</button></small></div></div>`).join(''):'<p class="muted">No expenses this month.</p>'}</div>`}
function history(){let a=[...monthly()].sort((x,y)=>y.date.localeCompare(x.date)||y.created-x.created);return `${monthHeader()}<div class="sectionhead"><h2>Transactions</h2><span class="pill">${a.length} entries</span></div><button class="action" id="addBtn">＋ Add expense</button><div class="card">${a.length?a.map(t=>`<div class="row tx"><div><strong>${esc(t.category)}</strong><small>${esc(t.date)}${t.subcategory?' · '+esc(t.subcategory):''}${t.note?' · '+esc(t.note):''}</small></div><div class="right"><strong>${fmt(t.amount)}</strong><small><button data-edit="${esc(t.id)}">Edit</button></small></div></div>`).join(''):'<div class="empty">No transactions yet.<br>Add your first expense to start tracking.</div>'}</div><div class="row"><span class="muted">Total spending</span><b>${fmt(total())}</b></div>`}
function finances(){let debts=Object.entries(data.debts),sum=debts.reduce((v,[,n])=>v+Number(n),0),goal=emergencyGoal(),p=Math.min(100,goal?data.savings/goal*100:100);return `<div class="eyebrow">Your financial plan</div><h1 style="margin:8px 0 20px;font-size:29px">Savings & debt</h1><button class="metric income-metric" id="incomeToggle" aria-expanded="${incomeExpanded}"><small>Net monthly income ▾</small><strong>${fmt(data.monthlyIncome)}</strong></button>${incomeExpanded?`<div class="card"><button class="action" id="paycheckBtn">＋ Add paycheck</button><div class="sectionhead"><h3>Paycheck history</h3></div>${[...data.paychecks].sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<div class="row"><span>${esc(p.date)} · ${fmt(p.net)} net</span><button class="secondary" data-pay-edit="${esc(p.id)}">Edit</button></div>`).join('')||'<p class="note">Your next paycheck can be recorded here. November 13 is already included in the opening pension estimate.</p>'}</div>`:''}<div class="sectionhead"><h2>Emergency fund</h2><button class="pill" id="savingsBtn" style="border:0;color:#e7f3ff">Update</button></div><div class="card"><div class="row"><div><div class="eyebrow">Current savings</div><h2>${fmt(data.savings)}</h2></div><div style="text-align:right"><div class="muted">Goal</div><b>${fmt(goal)}</b></div></div><div class="track"><div class="fill" style="width:${p}%"></div></div><p class="subtle">${fmt(Math.max(0,goal-data.savings))} to go</p></div>${retirementPanel()}${payrollDashboard()}<div class="sectionhead"><h2>Outstanding debt</h2><span class="pill">${fmt(sum)}</span></div>${debts.map(([n,v])=>`<div class="card row"><div><b>${esc(n)}</b><div class="muted" style="font-size:12px">${DEBTS.find(d=>d[0]===n)?.[2]||0}% APR</div></div><div style="text-align:right"><b>${fmt(v)}</b><div><button class="secondary" data-debt="${esc(n)}" style="padding:7px 10px;margin-top:7px;font-size:12px">Record payment</button></div></div></div>`).join('')}<div class="card"><b>Our plan</b><p class="note">Pay debts in APR order: OneMain → Chase Freedom → Upstart.</p></div><button class="secondary" id="backupBtn" style="width:100%;margin:10px 0">Export backup</button><button class="secondary" id="restoreBtn" style="width:100%">Restore backup</button></div>`}
function bind(){document.getElementById('payrollUpdate')?.addEventListener('click',payrollEditor);document.getElementById('monthCalendar')?.addEventListener('click',()=>{calendarExpanded=!calendarExpanded;render()});document.getElementById('addSubscription')?.addEventListener('click',newSubscription);document.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{let d=new Date(month+'-02T12:00:00');d.setMonth(d.getMonth()+Number(b.dataset.month));month=d.toISOString().slice(0,7);render()});document.getElementById('addBtn')?.addEventListener('click',()=>expense());document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{selectedCategory=selectedCategory===b.dataset.category?null:b.dataset.category;expandedSub=null;render()});document.getElementById('backCategory')?.addEventListener('click',()=>{selectedCategory=null;render()});document.querySelectorAll('[data-add-cat]').forEach(b=>b.onclick=()=>expense(null,b.dataset.addCat));document.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>{expandedSub=expandedSub===b.dataset.sub?null:b.dataset.sub;render()});document.querySelectorAll('[data-add-sub]').forEach(b=>b.onclick=()=>expense(null,selectedCategory,b.dataset.addSub));document.getElementById('manageSubLogos')?.addEventListener('click',()=>subscriptionSetup((data.subcategories.Subscriptions||[]).map(x=>x.name),0));document.getElementById('incomeToggle')?.addEventListener('click',()=>{incomeExpanded=!incomeExpanded;render()});document.querySelectorAll('[data-ret-detail]').forEach(b=>b.onclick=()=>retirementDetail(b.dataset.retDetail));document.getElementById('paycheckBtn')?.addEventListener('click',paycheckEditor);document.getElementById('retirementBtn')?.addEventListener('click',retirementEditor);document.getElementById('billsBtn')?.addEventListener('click',billsEditor);document.getElementById('calendarBtn')?.addEventListener('click',calendarView);document.querySelectorAll('[data-pay-edit]').forEach(b=>b.onclick=()=>paycheckEditor(b.dataset.payEdit));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>expense(data.transactions.find(t=>t.id===b.dataset.edit)));document.querySelectorAll('[data-debt]').forEach(b=>b.onclick=()=>debt(b.dataset.debt));document.getElementById('savingsBtn')?.addEventListener('click',savings);document.getElementById('backupBtn')?.addEventListener('click',backup);document.getElementById('restoreBtn')?.addEventListener('click',restore)}
function modal(html){document.getElementById('modalBody').innerHTML=html;document.getElementById('modal').hidden=false;document.querySelector('.sheet').scrollTop=0}function close(){document.getElementById('modal').hidden=true;document.querySelector('.sheet').style.transform='';document.querySelector('.sheet').style.transition=''}document.querySelector('[data-close]').onclick=close;document.getElementById('settingsBtn').onclick=settings;
function settings(){modal(`<h2>Manage categories</h2><p class="note">Editing ${esc(month)}. A monthly change affects only this month unless you choose “This month & all future months.” Previous months keep their own budgets.</p>${categories().map((c,i)=>`<div class="card row reorder-item" data-category-index="${i}"><button class="reorder-grip" aria-label="Drag to reorder ${esc(c.name)}" title="Drag to reorder">☰</button><div class="reorder-label"><b>${esc(c.icon)} ${esc(c.name)}</b><div class="muted">${fmt(getBudget(c.name))} for ${esc(month)}</div></div><button class="secondary" data-cat-edit="${i}">Edit</button></div>`).join('')}<button class="action" id="newCat">＋ Add category</button><div class="btnrow"><button class="secondary" id="rolloverBtn">Budget rollover</button><button class="secondary" id="subsBtn">Subcategories</button></div><div class="btnrow"><button class="secondary" id="settingsClose">Done</button><button class="secondary" id="resetBudgets">Restore original budgets</button></div><p class="note">Categories with transactions cannot be deleted. Renaming one also updates its historical transactions.</p>`);document.querySelectorAll('[data-cat-edit]').forEach(b=>b.onclick=()=>categoryEditor(Number(b.dataset.catEdit)));document.getElementById('newCat').onclick=()=>categoryEditor(-1);enableCategoryReordering();document.getElementById('settingsClose').onclick=close;document.getElementById('rolloverBtn').onclick=rolloverEditor;document.getElementById('subsBtn').onclick=subcategoryEditor;document.getElementById('resetBudgets').onclick=()=>{modal(`<h2>Restore budgets?</h2><p class="note">Restore original category amounts for ${esc(month)} only? Your transactions will not change.</p><div class="btnrow"><button class="secondary" id="no">Cancel</button><button class="primary" id="yes">Restore this month</button></div>`);document.getElementById('no').onclick=settings;document.getElementById('yes').onclick=()=>{data.monthOverrides[month]=Object.fromEntries(CATS.filter(([n])=>categories().some(c=>c.name===n)).map(([n,v])=>[n,v]));save();settings();render()}}}
function categoryEditor(i){let old=i>=0?categories()[i]:null;modal(`<h2>${old?'Edit':'Add'} category</h2><label class="field">Category name</label><input id="catName" maxlength="45" value="${esc(old?.name??'')}" placeholder="Category name"><label class="field">Icon (emoji)</label><input id="catIcon" maxlength="8" value="${esc(old?.icon??'🧾')}"><label class="field">Monthly budget ($)</label><input id="catBudget" type="number" min="0" step="0.01" inputmode="decimal" value="${old?getBudget(old.name).toFixed(2):'0.00'}"><label class="field">Apply budget change</label><select id="scope"><option value="month">${esc(month)} only</option><option value="future">This month & all future months</option></select><p class="note">Changes to this month won't affect earlier months. Future changes become the default from ${esc(month)} onward, unless another month's budget is explicitly overridden.</p><p id="catError" class="danger note"></p><div class="btnrow"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="saveCat">Save</button></div>${old?'<button class="secondary danger" id="deleteCat" style="width:100%;margin-top:12px">Delete category</button>':''}`);document.getElementById('cancel').onclick=settings;document.getElementById('saveCat').onclick=()=>{let name=document.getElementById('catName').value.trim(),icon=document.getElementById('catIcon').value.trim()||'🧾',raw=document.getElementById('catBudget').value,amount=Number(raw),scope=document.getElementById('scope').value,error=document.getElementById('catError');if(!name||!raw||!Number.isFinite(amount)||amount<0){error.textContent='Enter a name and a valid nonnegative budget.';return}if(categories().some((c,j)=>j!==i&&c.name.toLowerCase()===name.toLowerCase())){error.textContent='A category with that name already exists.';return}amount=Math.round(amount*100)/100;if(old&&name!==old.name){data.transactions.forEach(t=>{if(t.category===old.name)t.category=name});if(Object.prototype.hasOwnProperty.call(data.monthlyBudget,old.name)){data.monthlyBudget[name]=data.monthlyBudget[old.name];delete data.monthlyBudget[old.name]}Object.values(data.monthOverrides).forEach(o=>{if(Object.prototype.hasOwnProperty.call(o,old.name)){o[name]=o[old.name];delete o[old.name]}});data.futureBudgets.forEach(x=>{if(x.category===old.name)x.category=name})}if(old){categories()[i]={name,icon}}else{categories().push({name,icon});data.monthlyBudget[name]=0}if(scope==='month'){data.monthOverrides[month]??={};data.monthOverrides[month][name]=amount}else{data.futureBudgets=data.futureBudgets.filter(x=>!(x.category===name&&x.start===month));data.futureBudgets.push({category:name,start:month,amount});if(data.monthOverrides[month])delete data.monthOverrides[month][name]}save();settings();render()};if(old)document.getElementById('deleteCat').onclick=()=>{if(data.transactions.some(t=>t.category===old.name)){document.getElementById('catError').textContent='This category has transactions. Rename it instead so no history is lost.';return}categories().splice(i,1);delete data.monthlyBudget[old.name];Object.values(data.monthOverrides).forEach(o=>delete o[old.name]);data.futureBudgets=data.futureBudgets.filter(x=>x.category!==old.name);save();settings();render()}}

function expense(t,preset,presetSub){let edit=!!t,opts=categories().map(({name:n})=>`<option value="${esc(n)}" ${(t?.category||preset)===n?'selected':''}>${n}</option>`).join('');modal(`<h2>${edit?'Edit':'Add'} expense</h2><form id="expenseForm"><label class="field">Amount ($)</label><input id="amt" type="number" inputmode="decimal" min="0.01" step="0.01" required placeholder="0.00" value="${t?.amount??''}"><label class="field">Category</label><select id="cat">${opts}</select><label class="field">Subcategory (optional)</label><select id="subcat"></select><label class="field">Date</label><input id="date" type="date" required value="${t?.date??today()}"><label class="field">Note (optional)</label><input id="note" maxlength="140" placeholder="Where did you spend it?" value="${esc(t?.note??'')}"><div class="btnrow"><button type="button" class="secondary" id="cancel">Cancel</button><button class="primary">${edit?'Save changes':'Save expense'}</button></div>${edit?'<button type="button" class="secondary danger" id="delete" style="width:100%;margin-top:12px">Delete expense</button>':''}</form>`);const updateSubs=()=>{let c=document.getElementById('cat').value;document.getElementById('subcat').innerHTML='<option value="">None</option>'+(data.subcategories[c]||[]).map(x=>`<option value="${esc(x.name)}" ${(t?.subcategory||presetSub)===x.name?'selected':''}>${esc(x.name)}${x.budget?' · '+fmt(x.budget):''}</option>`).join('')};document.getElementById('cat').onchange=updateSubs;updateSubs();document.getElementById('cancel').onclick=close;document.getElementById('expenseForm').onsubmit=e=>{e.preventDefault();let amount=Number(document.getElementById('amt').value);if(!Number.isFinite(amount)||amount<=0)return;let entry={id:t?.id??(crypto.randomUUID?crypto.randomUUID():String(Date.now())),created:t?.created??Date.now(),amount:Math.round(amount*100)/100,category:document.getElementById('cat').value,subcategory:document.getElementById('subcat').value,date:document.getElementById('date').value,note:document.getElementById('note').value.trim()};if(edit)data.transactions=data.transactions.map(x=>x.id===t.id?entry:x);else data.transactions.push(entry);month=entry.date.slice(0,7);save();close();render()};if(edit)document.getElementById('delete').onclick=()=>{data.transactions=data.transactions.filter(x=>x.id!==t.id);save();close();render()}}
function savings(){modal(`<h2>Update savings</h2><p class="note">Enter a deposit (positive) or withdrawal (negative). This doesn't count as spending.</p><label class="field">Change in savings ($)</label><input id="change" type="number" step="0.01" inputmode="decimal" placeholder="331.48"><div class="btnrow"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="apply">Apply</button></div>`);document.getElementById('cancel').onclick=close;document.getElementById('apply').onclick=()=>{let n=Number(document.getElementById('change').value);if(!Number.isFinite(n)||!document.getElementById('change').value)return;data.savings=Math.round((data.savings+n)*100)/100;data.financeLog.push({date:today(),type:'savings',amount:n});save();close();render()}}
function debt(name){modal(`<h2>${esc(name)} payment</h2><p class="note">Enter how much your loan or card balance actually decreased (principal reduction). Interest and fees aren't calculated automatically.</p><label class="field">Principal reduction ($)</label><input id="change" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0.00"><div class="btnrow"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="apply">Apply</button></div>`);document.getElementById('cancel').onclick=close;document.getElementById('apply').onclick=()=>{let n=Number(document.getElementById('change').value);if(!Number.isFinite(n)||n<=0)return;data.debts[name]=Math.max(0,Math.round((data.debts[name]-n)*100)/100);data.financeLog.push({date:today(),type:'debt',name,amount:n});save();close();render()}}
function backup(){let blob=new Blob([JSON.stringify({app:'Spendwise',version:1,exportedAt:new Date().toISOString(),data},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`spendwise-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){modal(`<h2>Restore backup</h2><p class="note">Restoring replaces the data currently saved on this phone. Export a backup first if you want to keep it.</p><input type="file" id="file" accept="application/json,.json"><div class="btnrow"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="import">Restore</button></div><p id="error" class="danger note"></p>`);document.getElementById('cancel').onclick=close;document.getElementById('import').onclick=async()=>{try{let f=document.getElementById('file').files[0];if(!f)throw Error('Choose a backup file.');let v=JSON.parse(await f.text());if(v.app!=='Spendwise'||!v.data||!Array.isArray(v.data.transactions)||!v.data.monthlyBudget||!v.data.debts)throw Error('This is not a valid Spendwise backup.');data=v.data;migrate();save();close();render()}catch(e){document.getElementById('error').textContent=e.message}}}

// iPhone-safe category sorting: listen on document so moving DOM rows cannot lose the gesture.
function enableCategoryReordering(){
  const sheet=document.querySelector('.sheet');
  const list=[...document.querySelectorAll('.reorder-item')];
  list.forEach(item=>{
    const grip=item.querySelector('.reorder-grip');
    grip.addEventListener('touchstart',startTouch,{passive:false});
    grip.addEventListener('pointerdown',startMouse);
    function startTouch(e){
      if(e.touches.length!==1)return;
      e.preventDefault();
      begin(e.touches[0].clientY,'touch',e.touches[0].identifier);
    }
    function startMouse(e){
      if(e.pointerType==='touch'||e.button!==0)return;
      e.preventDefault();
      begin(e.clientY,'mouse',e.pointerId);
    }
    function begin(startY,kind,id){
      if(document.querySelector('.reorder-ghost'))return;
      const rect=item.getBoundingClientRect();
      const placeholder=document.createElement('div');
      placeholder.className='reorder-placeholder';
      placeholder.style.height=rect.height+'px';
      placeholder.style.marginBottom=getComputedStyle(item).marginBottom;
      item.before(placeholder);
      const ghost=item.cloneNode(true);
      ghost.classList.add('reorder-ghost','reordering');
      ghost.removeAttribute('data-category-index');
      ghost.style.cssText=`position:fixed;z-index:30;pointer-events:none;left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;height:${rect.height}px;margin:0;`;
      document.body.appendChild(ghost);
      item.style.display='none';
      const offset=startY-rect.top;
      let lastY=startY,active=true,scrollTimer=null;
      function position(y){
        lastY=y;
        ghost.style.top=(y-offset)+'px';
        const candidates=[...document.querySelectorAll('.reorder-item')].filter(r=>r!==item);
        const target=candidates.find(r=>y<r.getBoundingClientRect().top+r.getBoundingClientRect().height/2);
        if(target)target.before(placeholder);
        else if(candidates.length)candidates[candidates.length-1].after(placeholder);
      }
      function autoScroll(){
        if(!active)return;
        const r=sheet.getBoundingClientRect();
        if(lastY>r.bottom-65)sheet.scrollTop+=Math.min(18,(lastY-(r.bottom-65))*.55+3);
        else if(lastY<r.top+85)sheet.scrollTop-=Math.min(18,((r.top+85)-lastY)*.55+3);
        position(lastY);
        scrollTimer=requestAnimationFrame(autoScroll);
      }
      function onTouchMove(e){
        const t=[...e.changedTouches].find(t=>t.identifier===id);
        if(!t)return;
        e.preventDefault();position(t.clientY);
      }
      function onPointerMove(e){if(e.pointerId===id){e.preventDefault();position(e.clientY)}}
      function onTouchEnd(e){if([...e.changedTouches].some(t=>t.identifier===id))finish(false)}
      function onTouchCancel(e){if([...e.changedTouches].some(t=>t.identifier===id))finish(true)}
      function onPointerEnd(e){if(e.pointerId===id)finish(e.type==='pointercancel')}
      function finish(cancel){
        if(!active)return;
        active=false;cancelAnimationFrame(scrollTimer);
        document.removeEventListener('touchmove',onTouchMove);
        document.removeEventListener('touchend',onTouchEnd);
        document.removeEventListener('touchcancel',onTouchCancel);
        document.removeEventListener('pointermove',onPointerMove);
        document.removeEventListener('pointerup',onPointerEnd);
        document.removeEventListener('pointercancel',onPointerEnd);
        if(!cancel)placeholder.replaceWith(item);
        else placeholder.remove();
        item.style.display='';ghost.remove();
        if(cancel)return;
        const reordered=[...document.querySelectorAll('.reorder-item')].map(r=>categories()[Number(r.dataset.categoryIndex)]);
        if(reordered.length===categories().length){data.categories=reordered;save();settings();render()}
      }
      if(kind==='touch'){
        document.addEventListener('touchmove',onTouchMove,{passive:false});
        document.addEventListener('touchend',onTouchEnd);
        document.addEventListener('touchcancel',onTouchCancel);
      }else{
        document.addEventListener('pointermove',onPointerMove,{passive:false});
        document.addEventListener('pointerup',onPointerEnd);
        document.addEventListener('pointercancel',onPointerEnd);
      }
      scrollTimer=requestAnimationFrame(autoScroll);
    }
  });
}
// The top handle dismisses any modal without interfering with scrolling inside it.
(()=>{const handle=document.querySelector('.handle'),sheet=document.querySelector('.sheet');
  handle.addEventListener('pointerdown',e=>{
    if(e.button!==0&&e.pointerType==='mouse')return;
    const start=e.clientY;let offset=0;
    handle.setPointerCapture(e.pointerId);
    const move=ev=>{offset=Math.max(0,ev.clientY-start);sheet.style.transition='none';sheet.style.transform=`translateY(${offset}px)`};
    const finish=()=>{cleanup();sheet.style.transition='transform 180ms ease';if(offset>85){close()}else{sheet.style.transform='';setTimeout(()=>sheet.style.transition='',200)}};
    const cancel=()=>{cleanup();sheet.style.transform='';sheet.style.transition=''};
    const cleanup=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',finish);handle.removeEventListener('pointercancel',cancel)};
    handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',cancel);
  });
  handle.addEventListener('keydown',e=>{if(e.key==='Escape'||e.key==='Enter'||e.key===' '){e.preventDefault();close()}});
})();
// iOS Safari: suppress gesture zoom and double-tap zoom; preserve taps and scrolling.
document.addEventListener('gesturestart',e=>e.preventDefault(),{passive:false});
document.addEventListener('gesturechange',e=>e.preventDefault(),{passive:false});
let lastTouchEnd=0;
document.addEventListener('touchend',e=>{const now=Date.now();if(now-lastTouchEnd<300&&e.changedTouches.length===1)e.preventDefault();lastTouchEnd=now},{passive:false});


const money=n=>Math.round((Number(n)+Number.EPSILON)*100)/100;
function copersTotals(){let rows=payrollRows(),employee=payrollSum('employee'),city=payrollSum('city');if(!rows.length){return {employee:Number(data.retirement.employee)||0,city:Number(data.retirement.city)||0,source:'Manual estimate'}}let latest=rows.reduce((a,b)=>!a||b.date>a.date?b:a,null);for(let p of data.paychecks){if(p.date>latest.date){employee+=Number(p.employee||0);city+=Number(p.city||0)}}return {employee:money(employee),city:money(city),source:'Payroll history through '+latest.date}}
function retirementPanel(){let r=data.retirement,cp=copersTotals(),total=money(cp.employee+cp.city+r.a401+r.health);return `<div class="sectionhead"><h2>Retirement</h2></div><div class="card retirement-card"><div class="eyebrow">Combined retirement-related total</div><h2 class="retirement-total">${fmt(total)}</h2>${[['COPERS',cp.employee+cp.city],['401(a)',r.a401],['Retirement Health',r.health]].map(([name,value])=>`<button class="retirement-row" data-ret-detail="${esc(name)}"><strong>${fmt(value)}</strong><span>${esc(name)} ▸</span></button>`).join('')}<button class="secondary" id="retirementBtn" style="width:100%;margin-top:18px">Update accounts</button></div><div class="sectionhead"><h2>Bills & subscriptions</h2></div><button class="secondary" id="billsBtn" style="width:100%">Manage reminders</button>`}
function paycheckEditor(id){let old=data.paychecks.find(x=>x.id===id);modal(`<h2>${old?'Edit':'Record'} paycheck</h2><p class="note">Enter gross and net pay. 20% of net is deposited into savings; COPERS contributions are estimated from gross. Do not enter the Nov 13 paycheck again—it is included in the baseline.</p><label class="field">Pay date</label><input id="pd" type="date" value="${old?.date||today()}"><label class="field">Gross pay ($)</label><input id="pg" type="number" step=".01" min="0" value="${old?.gross??''}"><label class="field">Net pay ($)</label><input id="pn" type="number" step=".01" min="0" value="${old?.net??''}"><p id="preview" class="note"></p><p id="payError" class="danger note"></p><div class="btnrow"><button id="cancel" class="secondary">Cancel</button><button id="savePay" class="primary">Save paycheck</button></div>${old?'<button class="secondary danger" id="deletePay" style="width:100%">Delete paycheck</button>':''}`);const calc=()=>{let g=Number(document.getElementById('pg').value),n=Number(document.getElementById('pn').value),r=data.retirement;document.getElementById('preview').textContent=`Checking ${fmt(money(n*.8))} · Savings ${fmt(money(n*.2))} · Your COPERS ${fmt(money(g*r.employeeRate/100))} · City COPERS ${fmt(money(g*r.cityRate/100))}`};document.getElementById('pg').oninput=calc;document.getElementById('pn').oninput=calc;calc();document.getElementById('cancel').onclick=close;const apply=(p,sign)=>{data.savings=money(data.savings+sign*p.savings);};document.getElementById('savePay').onclick=()=>{let date=document.getElementById('pd').value,gross=Number(document.getElementById('pg').value),net=Number(document.getElementById('pn').value);if(!date||!document.getElementById('pg').value||!document.getElementById('pn').value||!Number.isFinite(gross)||!Number.isFinite(net)||gross<=0||net<0||net>gross){document.getElementById('payError').textContent='Enter valid date, gross and net pay.';return}if(data.paychecks.some(p=>p.date===date&&p.id!==id)){document.getElementById('payError').textContent='A paycheck already exists on this date. Edit that entry instead.';return}if(old)apply(old,-1);let r=data.retirement,p={id:old?.id||crypto.randomUUID(),date,gross:money(gross),net:money(net),savings:money(net*.2),employee:money(gross*r.employeeRate/100),city:money(gross*r.cityRate/100)};if(old)data.paychecks=data.paychecks.map(x=>x.id===old.id?p:x);else data.paychecks.push(p);apply(p,1);data.retirement.asOf=date>data.retirement.asOf?date:data.retirement.asOf;data.financeLog.push({date,type:'paycheck',amount:p.savings,paycheckId:p.id});save();close();render()};if(old)document.getElementById('deletePay').onclick=()=>{apply(old,-1);data.paychecks=data.paychecks.filter(p=>p.id!==old.id);save();close();render()}}
function retirementDetail(name){let r=data.retirement,cp=copersTotals(),details=name==='COPERS'?`<div class="row"><span>Your contributions</span><b>${fmt(cp.employee)}</b></div><div class="row"><span>City contributions</span><b>${fmt(cp.city)}</b></div><p class="note">${esc(cp.source)}. Contributions are not a withdrawable account balance.</p>`:name==='401(a)'?`<div class="row"><span>Statement date</span><b>${esc(r.a401Date)}</b></div>`:`<div class="row"><span>Statement date</span><b>${esc(r.healthDate)}</b></div>`;modal(`<h2>${esc(name)}</h2>${details}<button class="secondary" id="detailClose" style="width:100%">Done</button>`);document.getElementById('detailClose').onclick=close}
function retirementEditor(){let r=data.retirement;modal(`<h2>Retirement accounts</h2><p class="note">COPERS is calculated from payroll records when available; manual COPERS amounts are fallback values only. Update 401(a) and health balances from statements. COPERS percentages can change; existing paycheck entries keep their original calculated amounts.</p>${[['employee','Manual employee COPERS fallback'],['city','Manual employer COPERS fallback'],['a401','401(a) balance'],['a401Date','401(a) statement date'],['health','Retirement health balance'],['healthDate','Health statement date'],['employeeRate','Employee COPERS %'],['cityRate','City COPERS %']].map(([k,label])=>`<label class="field">${label}</label><input id="r_${k}" type="${k.endsWith('Date')?'date':'number'}" ${k.endsWith('Date')?'':'step=".01" min="0"'} value="${r[k]??0}">`).join('')}<p id="err" class="danger note"></p><div class="btnrow"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="saveRet">Save</button></div>`);document.getElementById('cancel').onclick=close;document.getElementById('saveRet').onclick=()=>{for(let k of ['employee','city','a401','health','employeeRate','cityRate']){let n=Number(document.getElementById('r_'+k).value);if(!Number.isFinite(n)||n<0||!document.getElementById('r_'+k).value){document.getElementById('err').textContent='Enter valid nonnegative numbers.';return}r[k]=money(n)}for(let k of ['a401Date','healthDate'])r[k]=document.getElementById('r_'+k).value;save();close();render()}}
function rolloverEditor(){modal(`<h2>Budget accumulation</h2><p class="note">Unspent budget is a virtual running total, NOT money held in savings. Continuous accumulation starts this month when first enabled.</p>${categories().map(c=>`<div class="card"><b>${esc(c.name)}</b><select data-roll="${esc(c.name)}"><option value="none">Monthly only (no accumulation)</option><option value="year" ${data.rollovers[c.name]==='year'?'selected':''}>Calendar year</option><option value="continuous" ${data.rollovers[c.name]==='continuous'?'selected':''}>Continuous</option></select></div>`).join('')}<div class="btnrow"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="saveRoll">Save</button></div>`);document.getElementById('cancel').onclick=settings;document.getElementById('saveRoll').onclick=()=>{data.rolloverStarts??={};document.querySelectorAll('[data-roll]').forEach(el=>{let c=el.dataset.roll;if(el.value==='continuous'&&data.rollovers[c]!=='continuous')data.rolloverStarts[c]=month;data.rollovers[c]=el.value});save();close();render()}}
function subcategoryEditor(){modal(`<h2>Subcategories</h2><p class="note">Optional subcategories have planning amounts, but parent budgets remain unchanged. Enter one per line as Name | Expected monthly amount.</p><label class="field">Parent category</label><select id="parentCat">${categories().map(c=>`<option>${esc(c.name)}</option>`).join('')}</select><label class="field">Subcategories</label><textarea id="subLines" rows="9" style="width:100%;border-radius:10px;padding:12px"></textarea><p id="err" class="danger note"></p><div class="btnrow"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="saveSubs">Save</button></div>`);const fill=()=>{document.getElementById('subLines').value=(data.subcategories[document.getElementById('parentCat').value]||[]).map(x=>`${x.name} | ${x.budget}`).join('\n')};document.getElementById('parentCat').onchange=fill;fill();document.getElementById('cancel').onclick=settings;document.getElementById('saveSubs').onclick=()=>{let lines=document.getElementById('subLines').value.split('\n').map(x=>x.trim()).filter(Boolean),arr=[];for(let line of lines){let [name,...rest]=line.split('|'),budget=Number(rest.join('|').trim()||0);if(!name.trim()||!Number.isFinite(budget)||budget<0){document.getElementById('err').textContent='Use Name | Amount on each line.';return}arr.push({name:name.trim(),budget:money(budget)})}let parent=document.getElementById('parentCat').value,prior=data.subcategories[parent]||[],newSubs=arr.filter(x=>!prior.some(y=>y.name===x.name));data.subcategories[parent]=arr;save();render();if(parent==='Subscriptions'&&newSubs.length){subscriptionSetup(newSubs.map(x=>x.name),0)}else close()}}
function subscriptionSetup(names,index){if(index>=names.length){close();render();return}let name=names[index],old=data.bills.find(b=>b.name===name);modal(`<h2>Set up ${esc(name)}</h2><p class="note">Add a recurring calendar reminder. This will not create expenses or deduct money.</p><label class="field">Frequency</label><select id="subFreq"><option value="monthly">Monthly</option><option value="yearly">Yearly</option></select><label class="field">Next billing date</label><input id="subDate" type="date" value="${today()}"><label class="field">Amount ($)</label><input id="subAmount" type="number" min="0" step=".01" value="${(data.subcategories.Subscriptions||[]).find(x=>x.name===name)?.budget||''}"><label class="field">Custom logo (optional)</label><input id="subLogo" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"><p class="note">Popular services show a recognizable icon automatically. You can replace it with your own image.</p><p id="subError" class="danger note"></p><div class="btnrow"><button class="secondary" id="skipSub">Skip</button><button class="primary" id="saveSub">Save reminder</button></div>`);document.getElementById('skipSub').onclick=()=>subscriptionSetup(names,index+1);document.getElementById('saveSub').onclick=async()=>{let date=document.getElementById('subDate').value,amount=Number(document.getElementById('subAmount').value),frequency=document.getElementById('subFreq').value;if(!date||!document.getElementById('subAmount').value||!Number.isFinite(amount)||amount<0){document.getElementById('subError').textContent='Enter a billing date and valid amount.';return}let file=document.getElementById('subLogo').files[0];if(file){if(file.size>2000000){document.getElementById('subError').textContent='Choose an image under 2 MB.';return}try{let image=new Image(),url=URL.createObjectURL(file);await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url});let canvas=document.createElement('canvas');canvas.width=80;canvas.height=80;canvas.getContext('2d').drawImage(image,0,0,80,80);data.subLogos??={};data.subLogos[name]=canvas.toDataURL('image/png');URL.revokeObjectURL(url)}catch(e){document.getElementById('subError').textContent='Could not read that image.';return}}if(old)data.bills=data.bills.filter(b=>b!==old);data.bills.push({id:crypto.randomUUID(),name,day:Number(date.slice(-2)),date,frequency,amount:money(amount)});save();subscriptionSetup(names,index+1)}}
function billOccurs(b,year,mon,day){if(b.frequency==='yearly'){let date=b.date||`${year}-${String(mon).padStart(2,'0')}-${String(b.day).padStart(2,'0')}`;return Number(date.slice(5,7))===mon&&Math.min(Number(date.slice(-2)),new Date(year,mon,0).getDate())===day&&`${year}-${String(mon).padStart(2,'0')}`>=date.slice(0,7)}let start=b.date?.slice(0,7);return (!start||`${year}-${String(mon).padStart(2,'0')}`>=start)&&Math.min(b.day,new Date(year,mon,0).getDate())===day}
function billsEditor(){modal(`<h2>Bill reminders</h2><p class="note">These are reminders only. They never post transactions or change your balances.</p><div id="billRows">${data.bills.map((b,i)=>`<div class="row"><div><b>${esc(b.name)}</b><small>Day ${b.day} · ${fmt(b.amount)}</small></div><button class="secondary" data-remove-bill="${i}">Remove</button></div>`).join('')}</div><label class="field">Bill or subscription</label><input id="billName" maxlength="70" placeholder="e.g. Amazon Prime"><label class="field">Due day of month (1–31)</label><input id="billDay" type="number" min="1" max="31"><label class="field">Expected amount ($)</label><input id="billAmount" type="number" min="0" step=".01"><p id="err" class="danger note"></p><div class="btnrow"><button class="secondary" id="cancel">Done</button><button class="primary" id="addBill">Add reminder</button></div>`);document.querySelectorAll('[data-remove-bill]').forEach(b=>b.onclick=()=>{data.bills.splice(Number(b.dataset.removeBill),1);save();billsEditor()});document.getElementById('cancel').onclick=close;document.getElementById('addBill').onclick=()=>{let name=document.getElementById('billName').value.trim(),day=Number(document.getElementById('billDay').value),amount=Number(document.getElementById('billAmount').value);if(!name||!Number.isInteger(day)||day<1||day>31||!Number.isFinite(amount)||amount<0||!document.getElementById('billAmount').value){document.getElementById('err').textContent='Enter name, due day (1–31) and expected amount.';return}data.bills.push({id:crypto.randomUUID(),name,day,amount:money(amount)});save();billsEditor()}}
function inlineCalendar(){let y=Number(month.slice(0,4)),m=Number(month.slice(5)),days=new Date(y,m,0).getDate(),first=new Date(y,m-1,1).getDay(),cells=Array.from({length:first},()=>'<div></div>'),payDates=new Set(data.paychecks.map(p=>p.date));let anchor=data.paySchedule?.anchor||'2026-11-13',cadence=data.paySchedule?.frequency||'biweekly';for(let d=1;d<=days;d++){let date=`${month}-${String(d).padStart(2,'0')}`,bills=data.bills.filter(b=>billOccurs(b,y,m,d)),daySpent=data.transactions.filter(t=>t.date===date).reduce((a,t)=>a+Number(t.amount),0);let isPay=payDates.has(date);if(!isPay&&cadence==='biweekly'){let delta=Math.round((new Date(date+'T12:00:00')-new Date(anchor+'T12:00:00'))/86400000);isPay=delta%14===0}cells.push(`<div class="calday"><b>${d}</b>${isPay?'<small class="payday">Payday</small>':''}${daySpent!==0?`<small class="daily-spend">${fmt(daySpent)}</small>`:''}${bills.map(b=>`<small>${esc(b.name)} · ${fmt(b.amount)} due</small>`).join('')}</div>`)}return `<div class="card inline-calendar"><p class="note">Daily net spending, paydays and upcoming reminders. Due dates do not count as spending.</p><div class="calendar-grid">${['S','M','T','W','T','F','S'].map(x=>`<b>${x}</b>`).join('')}${cells.join('')}</div></div>`}
function newSubscription(){modal(`<h2>Add subscription</h2><label class="field">Subscription name</label><input id="newSubName" maxlength="70" placeholder="Service name"><p id="subAddError" class="note danger"></p><div class="btnrow"><button class="secondary" id="subAddCancel">Cancel</button><button class="primary" id="subAddContinue">Continue</button></div>`);document.getElementById('subAddCancel').onclick=close;document.getElementById('subAddContinue').onclick=()=>{let name=document.getElementById('newSubName').value.trim();if(!name||name.length>70){document.getElementById('subAddError').textContent='Enter a subscription name.';return}if((data.subcategories.Subscriptions||[]).some(x=>x.name.toLowerCase()===name.toLowerCase())){document.getElementById('subAddError').textContent='Subscription already exists.';return}data.subcategories.Subscriptions??=[];data.subcategories.Subscriptions.push({name,budget:0});save();subscriptionSetup([name],0)}}
function calendarView(){let y=Number(month.slice(0,4)),m=Number(month.slice(5)),days=new Date(y,m,0).getDate(),first=new Date(y,m-1,1).getDay(),cells=Array.from({length:first},()=>'<div></div>');for(let d=1;d<=days;d++){let a=data.bills.filter(b=>billOccurs(b,y,m,d));cells.push(`<div class="calday"><b>${d}</b>${a.map(b=>`<small>${subIcon(b.name)} ${esc(b.name)}<br>${fmt(b.amount)}</small>`).join('')}</div>`)}modal(`<h2>Due-date calendar</h2><p class="note">${esc(month)} · reminders only, no transactions posted</p><div class="calendar-grid">${['S','M','T','W','T','F','S'].map(d=>`<b>${d}</b>`).join('')}${cells.join('')}</div><div class="row"><b>Expected this month</b><b>${fmt(data.bills.filter(b=>Array.from({length:days},(_,i)=>billOccurs(b,y,m,i+1)).some(Boolean)).reduce((a,b)=>a+b.amount,0))}</b></div><button class="secondary" id="doneCal" style="width:100%">Done</button>`);document.getElementById('doneCal').onclick=close}

document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;selectedCategory=null;expandedSub=null;render();window.scrollTo(0,0)});document.getElementById('homeBrand').onclick=()=>{close();tab='home';selectedCategory=null;expandedSub=null;render();window.scrollTo(0,0)};render();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();
